python - <<'PY'
import csv,glob,os,statistics,math
for f in glob.glob('../persistent/index_data/*.csv'):
 rows=list(csv.DictReader(open(f)))
 vals=[]
 for r in rows[-31:]:
  try: vals.append(float(r.get('close',r.get('Close'))))
  except: pass
 if len(vals)>5:
  ret=vals[-1]/vals[0]-1; vol=statistics.pstdev([vals[i]/vals[i-1]-1 for i in range(1,len(vals))])
  print(os.path.basename(f),rows[-1].get('date'), '30d',round(ret,4),'vol',round(vol,4),'last',vals[-1])
PY

