{"read_file": "import json
from pathlib import Path
import numpy as np
from alphacrafter.sim.utils import register_hook, get_stock_daily_data, get_index_daily_data, rebalance_to_weights

UNIVERSE = ["000300.SH", "SPX", "HSI", "N225", "SX5E", "000688.SH", "SOX", "NDX", "XAU", "COPPER", "WTI", "BTC", "ETH", "US10Y", "CN10Y"]
ROOT = Path(__file__).parent


def load_factors():
    try:
        data = json.loads((ROOT / "factors" / "factor_ensemble.json").read_text())
        fs = data.get("selected_factors", [])
        return fs if 0 < len(fs) <= 10 else []
    except Exception:
        return []


def factor_value(fid, p):
    # Exclude the current/incomplete row; only completed sessions are used.
    p = p[:-1]
    r = p[1:] / p[:-1] - 1.0
    def vol(n):
        return max(float(np.std(r[-n:])), 0.008)
    def ret(n):
        return float(p[-1] / p[-n-1] - 1.0)
    v20, v40 = vol(20), vol(40)
    neg = r[-40:][r[-40:] < 0]
    down = max(float(np.std(neg)) if len(neg) >= 5 else v40, 0.008)
    r20, r30, r40 = ret(20), ret(30), ret(40)
    if fid == "volatility_premium_20d":
        return v20
    if fid == "breadth_persistence_quality_40d":
        return r40 / v40
    if fid == "miner_2_20350621_breadth_conditioned_risk_reversal_20d":
        # Asset-level breadth proxy: reward persistent positive short-horizon returns,
        # while scaling by risk; this is deterministic and available for every asset.
        breadth = float(np.mean(r[-20:] > 0))
        return breadth * r20 / v20
    if fid == "miner_2_downside_adjusted_momentum_30d":
        return r30 / down
    if fid == "miner_3_20310515_risk_scaled_relative_deceleration_20d":
        return (r40 - 0.5 * r20) / v40
    if fid == "miner_3_20310501_vix_regime_reversal_20d":
        return -r20 / v20
    if fid == "miner_1_20350426_volatility_shock_reversal_40d":
        return -r40 / v40
    return 0.0


def ranks(values):
    out = {s: 0.5 for s in UNIVERSE}
    valid = sorted((float(v), s) for s, v in values.items() if np.isfinite(v))
    if not valid:
        return out
    for i, (_, s) in enumerate(valid):
        out[s] = (i + 1.0) / len(valid)
    return out


def make_weights(score):
    x = np.array([max(float(score[s]), 1e-8) for s in UNIVERSE])
    x /= x.sum()
    # 3%-14% bounds retain diversification in the intentionally small universe.
    for _ in range(25):
        y = np.clip(x, 0.03, 0.14)
        y /= y.sum()
        if np.max(np.abs(y - x)) < 1e-12:
            break
        x = y
    y = np.clip(y, 0.03, 0.14)
    y /= y.sum()
    return {s: float(y[i]) for i, s in enumerate(UNIVERSE)}


@register_hook
def strategy():
    factors = load_factors()
    if not factors:
        return
    prices = {}
    for s in UNIVERSE:
        try:
            df = get_stock_daily_data(symbol=s, days=260)
            if df is None:
                continue
            p = np.asarray(df.sort_values("date")["close"], dtype=float)
            if len(p) >= 130 and np.all(np.isfinite(p)) and np.all(p > 0):
                prices[s] = p
        except Exception:
            pass
    if len(prices) < 12:
        return

    score = {s: 0.5 for s in UNIVERSE}
    for f in factors:
        fid = str(f["factor_id"])
        direction = float(f.get("direction", 1))
        raw = {s: direction * factor_value(fid, p) for s, p in prices.items()}
        rr = ranks(raw)
        for s in UNIVERSE:
            score[s] += float(f["weight"]) * (rr[s] - 0.5)

    # Medium-high risk overlay: full investment is retained, but defensive tradables
    # receive a modest tilt when the observable VIX is elevated.
    try:
        d = get_index_daily_data(symbol="VIX", days=160)
        v = np.asarray(d.sort_values("date")["close"], dtype=float)
        if len(v) >= 120 and v[-1] > 1.05 * np.median(v[-120:]):
            for s in ("XAU", "US10Y", "CN10Y"):
                score[s] *= 1.25
            for s in ("BTC", "ETH", "SOX", "NDX", "WTI"):
                score[s] *= 0.82
    except Exception:
        pass

    target = make_weights(score)
    vals = np.array([score[s] for s in UNIVERSE], dtype=float)
    z = (vals - vals.mean()) / max(vals.std(), 1e-9)
    forecast = {s: float(0.01 * z[i]) for i, s in enumerate(UNIVERSE)}
    rebalance_to_weights(target, forecast_returns=forecast,
                         factor_ids=[str(f["factor_id"]) for f in factors],
                         horizon_days=10)
"}

